"""SentriX Dashboard V60 — frontend complet reconstruit.

Cette version ne dépend d'aucune image générée ni d'aucun framework externe. Elle reprend
uniquement l'esprit d'un panneau de configuration sombre à double barre latérale et conserve
les API sécurisées déjà présentes dans :mod:`web.dashboard`.

Le document est injecté juste avant le gel V55, après l'installation des routes produit.
Ainsi les anciennes couches de présentation peuvent garder leurs endpoints sans réécrire
l'interface finalement servie sur ``/app``.
"""
from __future__ import annotations

import logging

logger = logging.getLogger("bot.dashboard-v60")

